DO $publish$ DECLARE j jsonb := $expected$[{"language":"es","slug":"garbanzos-cremosos-tomates-secos","public_path":"/garbanzos-cremosos-tomates-secos","title":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas","excerpt":"Garbanzos de bote en salsa cremosa de tomates secos, espinacas y parmesano. Nuestra versión de Marry Me Chickpeas se hace en una sartén y rinde cuatro porciones.","summary":"Garbanzos de bote en salsa cremosa de tomates secos, espinacas y parmesano. Nuestra versión de Marry Me Chickpeas se hace en una sartén y rinde cuatro porciones.","notes":"<p>Usa garbanzos ya cocidos; los secos requieren otra cocción. El parmesano tradicional puede contener cuajo animal: para una versión vegetariana estricta elige queso con cuajo microbiano. Contiene leche. Refrigera las sobras antes de 2 horas y consúmelas en 3 días; recalienta con un poco de agua, sin hervir fuerte. La nutrición cuenta toda la sal indicada, aunque puedas necesitar menos.</p><h2>También puedes preparar</h2><ul><li><a href=\"/pizza-beans-alubias-gratinadas\">Pizza beans: alubias blancas con tomate y mozzarella</a></li><li><a href=\"/ensalada-lentejas-zanahoria-mostaza\">Ensalada de lentejas con zanahoria asada y mostaza</a></li></ul>","content_html":"<p>Garbanzos de bote en salsa cremosa de tomates secos, espinacas y parmesano. Nuestra versión de Marry Me Chickpeas se hace en una sartén y rinde cuatro porciones.</p><p>Usa garbanzos ya cocidos; los secos requieren otra cocción. El parmesano tradicional puede contener cuajo animal: para una versión vegetariana estricta elige queso con cuajo microbiano. Contiene leche. Refrigera las sobras antes de 2 horas y consúmelas en 3 días; recalienta con un poco de agua, sin hervir fuerte. La nutrición cuenta toda la sal indicada, aunque puedas necesitar menos.</p><h2>También puedes preparar</h2><ul><li><a href=\"/pizza-beans-alubias-gratinadas\">Pizza beans: alubias blancas con tomate y mozzarella</a></li><li><a href=\"/ensalada-lentejas-zanahoria-mostaza\">Ensalada de lentejas con zanahoria asada y mostaza</a></li></ul>","ingredients":[{"name":"Garbanzos cocidos, escurridos","amount":"480","unit":"g"},{"name":"Cebolla pelada","amount":"100","unit":"g"},{"name":"Aceite de oliva","amount":"15","unit":"g"},{"name":"Ajo pelado","amount":"10","unit":"g"},{"name":"Tomates secos en aceite, escurridos","amount":"60","unit":"g"},{"name":"Concentrado de tomate","amount":"20","unit":"g"},{"name":"Caldo de verduras","amount":"200","unit":"ml"},{"name":"Crema de leche con 35 % de grasa","amount":"150","unit":"g"},{"name":"Espinacas frescas","amount":"100","unit":"g"},{"name":"Queso parmesano rallado","amount":"30","unit":"g"},{"name":"Orégano seco","amount":"1","unit":"g"},{"name":"Sal","amount":"2","unit":"g"},{"name":"Pimienta negra molida","amount":"0.5","unit":"g"}],"steps":[{"title":"Prepara los ingredientes","content":"Escurre y enjuaga los garbanzos hasta obtener 480 g. Pica la cebolla y el ajo, corta los tomates secos escurridos en tiras y lava las espinacas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-01.webp","image_alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas: Prepara los ingredientes"},{"title":"Sofríe la cebolla","content":"Calienta 15 g de aceite en una sartén amplia a fuego medio. Añade la cebolla y cocina 6–7 minutos, removiendo, hasta ablandarla sin quemarla.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-02.webp","image_alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas: Sofríe la cebolla"},{"title":"Concentra el sabor","content":"Añade el ajo, los tomates secos, 20 g de concentrado de tomate y el orégano. Remueve durante 2 minutos para cocinar la pasta de tomate.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-03.webp","image_alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas: Concentra el sabor"},{"title":"Incorpora los garbanzos","content":"Vierte los 200 ml de caldo y raspa el fondo con una cuchara. Añade los garbanzos y deja hervir suavemente 5 minutos, sin tapar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-04.webp","image_alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas: Incorpora los garbanzos"},{"title":"Añade la crema","content":"Baja el fuego e incorpora los 150 g de crema de leche. Cocina a hervor muy suave 6–8 minutos, hasta que la salsa cubra los garbanzos sin secarse.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-05.webp","image_alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas: Añade la crema"},{"title":"Marchita las espinacas","content":"Añade las espinacas en dos tandas y mezcla durante 2 minutos, hasta que pierdan volumen y queden repartidas. No las hiervas más de lo necesario.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-06.webp","image_alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas: Marchita las espinacas"},{"title":"Termina fuera del fuego","content":"Apaga el fuego y mezcla el parmesano y la pimienta. Prueba antes de añadir los 2 g de sal: el caldo y el queso pueden aportar suficiente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-07.webp","image_alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas: Termina fuera del fuego"},{"title":"Sirve","content":"Reparte en cuatro platos y sirve caliente. El pan o el arroz para acompañar no están incluidos en las cantidades ni en la nutrición de esta receta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-08.webp","image_alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas: Sirve"}],"category":"Platos principales","course":"Platos principales","cuisine":"Estadounidense de inspiración italiana","difficulty":"Fácil","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas"}],"video_urls":[],"keywords":["Garbanzos cremosos con tomates secos: Marry Me Chickpeas","Garbanzos cocidos, escurridos","Cebolla pelada"],"nutrition":{"calories":415,"protein_g":14.5,"carbs_g":38.0,"fat_g":24.4,"saturated_fat_g":10.9,"fiber_g":9.8,"sodium_mg":759.0,"estimated":true,"serving_size":"1 de 4 porciones","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Suma de referencias por peso, dividida entre las porciones; todos los ingredientes principales contabilizados.","note":"Estimación orientativa, no medición del plato cocinado. Las marcas y el escurrido cambian los valores; los nutrientes sin dato completo no se muestran. Referencias genéricas para mostaza preparada, crema, boniato, aceite y chocolate; las variedades y marcas concretas pueden diferir."},"seo":{"title":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas","description":"Garbanzos de bote en salsa cremosa de tomates secos, espinacas y parmesano. Nuestra versión de Marry Me Chickpeas se hace en una sartén y rinde cuatro porciones.","image_alt":"Garbanzos cremosos con tomates secos: Marry Me Chickpeas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-16x9.webp"],"faq":[{"q":"¿Qué significa Marry Me Chickpeas?","a":"Es el nombre popular de unos garbanzos con salsa cremosa y tomates secos, inspirados en Marry Me Chicken. Esta preparación no lleva pollo."},{"q":"¿Puedo usar leche en vez de crema?","a":"No en la misma proporción si buscas esta textura. La leche tiene menos grasa y espesa de otra forma; esta receta se calcula para crema de leche."},{"q":"¿Puedo congelarlos?","a":"Sí, aunque la salsa puede separarse. Descongela en nevera y recalienta suavemente removiendo; la textura recién hecha es mejor."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"57abe9a1-3a8e-4a90-8b28-4fefee556e3f"},{"language":"de","slug":"marry-me-kichererbsen-cremige-sauce","public_path":"/de/marry-me-kichererbsen-cremige-sauce","title":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat","excerpt":"Kichererbsen in cremiger Sauce mit getrockneten Tomaten, Spinat und Parmesan. Unsere Marry Me Chickpeas gelingen in einer Pfanne und ergeben vier Portionen.","summary":"Kichererbsen in cremiger Sauce mit getrockneten Tomaten, Spinat und Parmesan. Unsere Marry Me Chickpeas gelingen in einer Pfanne und ergeben vier Portionen.","notes":"<p>Bereits gekochte Kichererbsen verwenden; getrocknete benötigen eine eigene Garzeit. Traditioneller Parmesan kann tierisches Lab enthalten. Für eine streng vegetarische Variante Käse mit mikrobiellem Lab wählen. Enthält Milch. Reste innerhalb von 2 Stunden kühlen und in 3 Tagen verbrauchen; mit wenig Wasser sanft aufwärmen. Die Nährwerte berücksichtigen die gesamte angegebene Salzmenge.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/pizza-bohnen-mozzarella\">Pizza Beans: weiße Bohnen mit Tomaten und Mozzarella</a></li><li><a href=\"/de/linsensalat-ofenmoehren-dijon-senf\">Linsensalat mit Ofenmöhren, Walnüssen und Dijon-Senf</a></li></ul>","content_html":"<p>Kichererbsen in cremiger Sauce mit getrockneten Tomaten, Spinat und Parmesan. Unsere Marry Me Chickpeas gelingen in einer Pfanne und ergeben vier Portionen.</p><p>Bereits gekochte Kichererbsen verwenden; getrocknete benötigen eine eigene Garzeit. Traditioneller Parmesan kann tierisches Lab enthalten. Für eine streng vegetarische Variante Käse mit mikrobiellem Lab wählen. Enthält Milch. Reste innerhalb von 2 Stunden kühlen und in 3 Tagen verbrauchen; mit wenig Wasser sanft aufwärmen. Die Nährwerte berücksichtigen die gesamte angegebene Salzmenge.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/pizza-bohnen-mozzarella\">Pizza Beans: weiße Bohnen mit Tomaten und Mozzarella</a></li><li><a href=\"/de/linsensalat-ofenmoehren-dijon-senf\">Linsensalat mit Ofenmöhren, Walnüssen und Dijon-Senf</a></li></ul>","ingredients":[{"name":"Gekochte Kichererbsen, abgetropft","amount":"480","unit":"g"},{"name":"Geschälte Zwiebel","amount":"100","unit":"g"},{"name":"Olivenöl","amount":"15","unit":"g"},{"name":"Geschälter Knoblauch","amount":"10","unit":"g"},{"name":"Getrocknete Tomaten in Öl, abgetropft","amount":"60","unit":"g"},{"name":"Tomatenmark","amount":"20","unit":"g"},{"name":"Gemüsebrühe","amount":"200","unit":"ml"},{"name":"Sahne mit 35 % Fett","amount":"150","unit":"g"},{"name":"Frischer Spinat","amount":"100","unit":"g"},{"name":"Geriebener Parmesan","amount":"30","unit":"g"},{"name":"Getrockneter Oregano","amount":"1","unit":"g"},{"name":"Salz","amount":"2","unit":"g"},{"name":"Gemahlener schwarzer Pfeffer","amount":"0.5","unit":"g"}],"steps":[{"title":"Vorbereiten","content":"Kichererbsen abgießen und abspülen; 480 g abwiegen. Zwiebel und Knoblauch hacken, abgetropfte Tomaten in Streifen schneiden und Spinat waschen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-01.webp","image_alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat: Vorbereiten"},{"title":"Zwiebel dünsten","content":"15 g Öl in einer großen Pfanne bei mittlerer Hitze erwärmen. Zwiebel unter Rühren 6–7 Minuten weich dünsten, ohne sie zu verbrennen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-02.webp","image_alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat: Zwiebel dünsten"},{"title":"Würzbasis rösten","content":"Knoblauch, getrocknete Tomaten, 20 g Tomatenmark und Oregano zugeben. Unter Rühren 2 Minuten garen, damit das Tomatenmark mitröstet.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-03.webp","image_alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat: Würzbasis rösten"},{"title":"Kichererbsen zugeben","content":"200 ml Brühe angießen und den Pfannenboden mit einem Löffel lösen. Kichererbsen zufügen und offen 5 Minuten sanft köcheln lassen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-04.webp","image_alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat: Kichererbsen zugeben"},{"title":"Sahne einrühren","content":"Hitze reduzieren und 150 g Sahne zugeben. Bei sehr mildem Köcheln 6–8 Minuten garen, bis die Sauce die Kichererbsen umhüllt, ohne trocken zu werden.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-05.webp","image_alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat: Sahne einrühren"},{"title":"Spinat zusammenfallen lassen","content":"Spinat in zwei Portionen zufügen und 2 Minuten unterheben, bis er zusammenfällt und gleichmäßig verteilt ist. Nicht unnötig lange kochen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-06.webp","image_alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat: Spinat zusammenfallen lassen"},{"title":"Ohne Hitze vollenden","content":"Herd ausschalten und Parmesan sowie Pfeffer einrühren. Vor Zugabe der 2 g Salz probieren: Brühe und Käse können bereits genug Salz enthalten.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-07.webp","image_alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat: Ohne Hitze vollenden"},{"title":"Anrichten","content":"Auf vier Teller verteilen und heiß servieren. Brot oder Reis als Beilage sind weder in den Mengen noch in den Nährwerten enthalten.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-08.webp","image_alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat: Anrichten"}],"category":"Hauptgerichte","course":"Hauptgerichte","cuisine":"US-amerikanisch, italienisch inspiriert","difficulty":"Einfach","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat"}],"video_urls":[],"keywords":["Marry Me Kichererbsen mit getrockneten Tomaten und Spinat","Gekochte Kichererbsen, abgetropft","Geschälte Zwiebel"],"nutrition":{"calories":415,"protein_g":14.5,"carbs_g":38.0,"fat_g":24.4,"saturated_fat_g":10.9,"fiber_g":9.8,"sodium_mg":759.0,"estimated":true,"serving_size":"1 von 4 Portionen","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Referenzwerte nach Zutatengewicht summiert und durch die Portionen geteilt.","note":"Ungefähre Schätzung, keine Messung des fertigen Gerichts. Marken und Abtropfen verändern die Werte; unvollständige Nährstoffdaten werden nicht angezeigt. Generische Referenzen für Senf, Sahne, Süßkartoffeln, Öl und Schokolade; Sorten und Marken können abweichen."},"seo":{"title":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat","description":"Kichererbsen in cremiger Sauce mit getrockneten Tomaten, Spinat und Parmesan. Unsere Marry Me Chickpeas gelingen in einer Pfanne und ergeben vier Portionen.","image_alt":"Marry Me Kichererbsen mit getrockneten Tomaten und Spinat","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-16x9.webp"],"faq":[{"q":"Was bedeutet Marry Me Chickpeas?","a":"So werden Kichererbsen in cremiger Sauce mit getrockneten Tomaten genannt, angelehnt an Marry Me Chicken. Dieses Rezept enthält kein Hähnchen."},{"q":"Kann Milch die Sahne ersetzen?","a":"Nicht mengenmäßig gleich, wenn dieselbe Konsistenz gewünscht ist. Milch enthält weniger Fett und bindet anders; berechnet wurde das Rezept mit Sahne."},{"q":"Kann ich das Gericht einfrieren?","a":"Ja, allerdings kann sich die Sauce trennen. Im Kühlschrank auftauen und vorsichtig unter Rühren erhitzen; frisch ist die Textur besser."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"57abe9a1-3a8e-4a90-8b28-4fefee556e3f"},{"language":"en","slug":"marry-me-chickpeas-creamy-skillet","public_path":"/en/marry-me-chickpeas-creamy-skillet","title":"Marry Me Chickpeas with sun-dried tomatoes and spinach","excerpt":"Canned chickpeas simmered in a creamy sun-dried tomato, spinach and Parmesan sauce. This one-pan Marry Me Chickpeas recipe makes four comforting portions.","summary":"Canned chickpeas simmered in a creamy sun-dried tomato, spinach and Parmesan sauce. This one-pan Marry Me Chickpeas recipe makes four comforting portions.","notes":"<p>Use already cooked chickpeas; dried ones need a separate cooking process. Traditional Parmesan may use animal rennet: choose cheese made with microbial rennet for a strict vegetarian version. Contains milk. Refrigerate leftovers within 2 hours and use within 3 days; reheat gently with a little water. Nutrition includes all the listed salt, even if you use less.</p><h2>You may also like</h2><ul><li><a href=\"/en/pizza-beans\">Pizza beans with tomato and mozzarella</a></li><li><a href=\"/en/warm-lentil-roasted-carrot-salad\">Warm lentil and roasted carrot salad with Dijon dressing</a></li></ul>","content_html":"<p>Canned chickpeas simmered in a creamy sun-dried tomato, spinach and Parmesan sauce. This one-pan Marry Me Chickpeas recipe makes four comforting portions.</p><p>Use already cooked chickpeas; dried ones need a separate cooking process. Traditional Parmesan may use animal rennet: choose cheese made with microbial rennet for a strict vegetarian version. Contains milk. Refrigerate leftovers within 2 hours and use within 3 days; reheat gently with a little water. Nutrition includes all the listed salt, even if you use less.</p><h2>You may also like</h2><ul><li><a href=\"/en/pizza-beans\">Pizza beans with tomato and mozzarella</a></li><li><a href=\"/en/warm-lentil-roasted-carrot-salad\">Warm lentil and roasted carrot salad with Dijon dressing</a></li></ul>","ingredients":[{"name":"Cooked chickpeas, drained","amount":"480","unit":"g"},{"name":"Peeled onion","amount":"100","unit":"g"},{"name":"Olive oil","amount":"15","unit":"g"},{"name":"Peeled garlic","amount":"10","unit":"g"},{"name":"Oil-packed sun-dried tomatoes, drained","amount":"60","unit":"g"},{"name":"Tomato paste","amount":"20","unit":"g"},{"name":"Vegetable broth","amount":"200","unit":"ml"},{"name":"Heavy cream, 35% fat","amount":"150","unit":"g"},{"name":"Fresh spinach","amount":"100","unit":"g"},{"name":"Grated Parmesan cheese","amount":"30","unit":"g"},{"name":"Dried oregano","amount":"1","unit":"g"},{"name":"Salt","amount":"2","unit":"g"},{"name":"Ground black pepper","amount":"0.5","unit":"g"}],"steps":[{"title":"Prepare the ingredients","content":"Drain and rinse the chickpeas to obtain 480 g. Chop the onion and garlic, slice the drained tomatoes into strips and wash the spinach.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-01.webp","image_alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach: Prepare the ingredients"},{"title":"Soften the onion","content":"Heat 15 g oil in a wide skillet over medium heat. Add the onion and cook, stirring, for 6–7 minutes until softened without burning.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-02.webp","image_alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach: Soften the onion"},{"title":"Build the sauce base","content":"Add the garlic, sun-dried tomatoes, 20 g tomato paste and oregano. Stir for 2 minutes to cook the tomato paste.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-03.webp","image_alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach: Build the sauce base"},{"title":"Add the chickpeas","content":"Pour in 200 ml broth and scrape the bottom with a spoon. Add the chickpeas and simmer gently, uncovered, for 5 minutes.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-04.webp","image_alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach: Add the chickpeas"},{"title":"Stir in the cream","content":"Lower the heat and add 150 g cream. Simmer very gently for 6–8 minutes, until the sauce coats the chickpeas without drying out.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-05.webp","image_alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach: Stir in the cream"},{"title":"Wilt the spinach","content":"Add the spinach in two batches and stir for 2 minutes until wilted and evenly distributed. Avoid unnecessary prolonged boiling.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-06.webp","image_alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach: Wilt the spinach"},{"title":"Finish off the heat","content":"Turn off the heat and stir in the Parmesan and pepper. Taste before adding the 2 g salt: the broth and cheese may already provide enough.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-07.webp","image_alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach: Finish off the heat"},{"title":"Serve","content":"Divide between four plates and serve hot. Bread or rice served alongside is not included in the ingredient quantities or nutrition.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-08.webp","image_alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach: Serve"}],"category":"Main dishes","course":"Main dishes","cuisine":"American, Italian inspired","difficulty":"Easy","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach"}],"video_urls":[],"keywords":["Marry Me Chickpeas with sun-dried tomatoes and spinach","Cooked chickpeas, drained","Peeled onion"],"nutrition":{"calories":415,"protein_g":14.5,"carbs_g":38.0,"fat_g":24.4,"saturated_fat_g":10.9,"fiber_g":9.8,"sodium_mg":759.0,"estimated":true,"serving_size":"1 of 4 servings","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Reference nutrients summed by ingredient weight and divided by servings.","note":"Approximate estimate, not a measurement of the cooked dish. Brands and draining change values; nutrients with incomplete data are omitted. Generic references for prepared mustard, cream, sweet potato, oil and chocolate; specific varieties and brands can differ."},"seo":{"title":"Marry Me Chickpeas with sun-dried tomatoes and spinach","description":"Canned chickpeas simmered in a creamy sun-dried tomato, spinach and Parmesan sauce. This one-pan Marry Me Chickpeas recipe makes four comforting portions.","image_alt":"Marry Me Chickpeas with sun-dried tomatoes and spinach","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-16x9.webp"],"faq":[{"q":"What are Marry Me Chickpeas?","a":"Chickpeas in a creamy sun-dried tomato sauce inspired by Marry Me Chicken. This recipe contains no chicken."},{"q":"Can I replace the cream with milk?","a":"Not in the same quantity for this texture. Milk has less fat and thickens differently; this formulation is calculated for heavy cream."},{"q":"Can I freeze it?","a":"Yes, although the sauce may separate. Thaw in the refrigerator and reheat gently while stirring; the texture is best freshly made."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"57abe9a1-3a8e-4a90-8b28-4fefee556e3f"},{"language":"fr","slug":"pois-chiches-cremeux-tomates-sechees","public_path":"/fr/pois-chiches-cremeux-tomates-sechees","title":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas","excerpt":"Des pois chiches en conserve dans une sauce aux tomates séchées, épinards et parmesan. Cette version de Marry Me Chickpeas se prépare à la poêle pour quatre.","summary":"Des pois chiches en conserve dans une sauce aux tomates séchées, épinards et parmesan. Cette version de Marry Me Chickpeas se prépare à la poêle pour quatre.","notes":"<p>Utilisez des pois chiches déjà cuits ; les secs demandent une cuisson séparée. Le parmesan traditionnel peut contenir de la présure animale : choisissez un fromage à présure microbienne pour une version strictement végétarienne. Contient du lait. Réfrigérez les restes avant 2 heures et consommez sous 3 jours ; réchauffez doucement avec un peu d’eau. Toute la quantité de sel indiquée est comptée dans la nutrition.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/pizza-beans-haricots-mozzarella\">Pizza beans : haricots blancs, tomate et mozzarella</a></li><li><a href=\"/fr/salade-lentilles-carottes-roties-moutarde\">Salade de lentilles, carottes rôties et moutarde de Dijon</a></li></ul>","content_html":"<p>Des pois chiches en conserve dans une sauce aux tomates séchées, épinards et parmesan. Cette version de Marry Me Chickpeas se prépare à la poêle pour quatre.</p><p>Utilisez des pois chiches déjà cuits ; les secs demandent une cuisson séparée. Le parmesan traditionnel peut contenir de la présure animale : choisissez un fromage à présure microbienne pour une version strictement végétarienne. Contient du lait. Réfrigérez les restes avant 2 heures et consommez sous 3 jours ; réchauffez doucement avec un peu d’eau. Toute la quantité de sel indiquée est comptée dans la nutrition.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/pizza-beans-haricots-mozzarella\">Pizza beans : haricots blancs, tomate et mozzarella</a></li><li><a href=\"/fr/salade-lentilles-carottes-roties-moutarde\">Salade de lentilles, carottes rôties et moutarde de Dijon</a></li></ul>","ingredients":[{"name":"Pois chiches cuits, égouttés","amount":"480","unit":"g"},{"name":"Oignon épluché","amount":"100","unit":"g"},{"name":"Huile d’olive","amount":"15","unit":"g"},{"name":"Ail épluché","amount":"10","unit":"g"},{"name":"Tomates séchées à l’huile, égouttées","amount":"60","unit":"g"},{"name":"Concentré de tomate","amount":"20","unit":"g"},{"name":"Bouillon de légumes","amount":"200","unit":"ml"},{"name":"Crème liquide à 35 % de matière grasse","amount":"150","unit":"g"},{"name":"Épinards frais","amount":"100","unit":"g"},{"name":"Parmesan râpé","amount":"30","unit":"g"},{"name":"Origan séché","amount":"1","unit":"g"},{"name":"Sel","amount":"2","unit":"g"},{"name":"Poivre noir moulu","amount":"0.5","unit":"g"}],"steps":[{"title":"Préparer les ingrédients","content":"Égouttez et rincez les pois chiches pour obtenir 480 g. Hachez l’oignon et l’ail, détaillez les tomates égouttées en lanières et lavez les épinards.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-01.webp","image_alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas: Préparer les ingrédients"},{"title":"Faire suer l’oignon","content":"Chauffez 15 g d’huile dans une grande poêle à feu moyen. Faites revenir l’oignon 6–7 minutes en remuant, jusqu’à ce qu’il soit tendre sans brûler.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-02.webp","image_alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas: Faire suer l’oignon"},{"title":"Concentrer les saveurs","content":"Ajoutez ail, tomates séchées, 20 g de concentré et origan. Remuez pendant 2 minutes pour cuire le concentré de tomate.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-03.webp","image_alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas: Concentrer les saveurs"},{"title":"Ajouter les pois chiches","content":"Versez 200 ml de bouillon et grattez le fond avec une cuillère. Ajoutez les pois chiches et laissez frémir 5 minutes à découvert.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-04.webp","image_alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas: Ajouter les pois chiches"},{"title":"Incorporer la crème","content":"Baissez le feu et ajoutez 150 g de crème. Laissez frémir très doucement 6–8 minutes, jusqu’à obtenir une sauce nappante sans assécher les pois chiches.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-05.webp","image_alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas: Incorporer la crème"},{"title":"Faire tomber les épinards","content":"Ajoutez les épinards en deux fois et mélangez pendant 2 minutes, jusqu’à ce qu’ils réduisent et soient bien répartis. Évitez une cuisson prolongée.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-06.webp","image_alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas: Faire tomber les épinards"},{"title":"Terminer hors du feu","content":"Coupez le feu, incorporez parmesan et poivre. Goûtez avant d’ajouter les 2 g de sel : le bouillon et le fromage peuvent suffire.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-07.webp","image_alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas: Terminer hors du feu"},{"title":"Servir","content":"Répartissez dans quatre assiettes et servez chaud. Le pain ou le riz d’accompagnement ne sont pas compris dans les quantités ni dans la nutrition.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-08.webp","image_alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas: Servir"}],"category":"Plats principaux","course":"Plats principaux","cuisine":"Américaine, inspiration italienne","difficulty":"Facile","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas"}],"video_urls":[],"keywords":["Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas","Pois chiches cuits, égouttés","Oignon épluché"],"nutrition":{"calories":415,"protein_g":14.5,"carbs_g":38.0,"fat_g":24.4,"saturated_fat_g":10.9,"fiber_g":9.8,"sodium_mg":759.0,"estimated":true,"serving_size":"1 des 4 portions","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somme des références selon le poids des ingrédients, divisée par le nombre de portions.","note":"Estimation indicative, pas une mesure du plat cuisiné. Marques et égouttage changent les valeurs ; les nutriments incomplets ne sont pas affichés. Références génériques pour moutarde préparée, crème, patate douce, huile et chocolat ; variétés et marques peuvent différer."},"seo":{"title":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas","description":"Des pois chiches en conserve dans une sauce aux tomates séchées, épinards et parmesan. Cette version de Marry Me Chickpeas se prépare à la poêle pour quatre.","image_alt":"Pois chiches crémeux aux tomates séchées : Marry Me Chickpeas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-16x9.webp"],"faq":[{"q":"Que signifie Marry Me Chickpeas ?","a":"C’est le nom courant de pois chiches dans une sauce crémeuse aux tomates séchées, inspirée de Marry Me Chicken. Cette préparation ne contient pas de poulet."},{"q":"Peut-on remplacer la crème par du lait ?","a":"Pas à quantité égale pour cette texture. Le lait est moins gras et épaissit différemment ; la recette est calculée avec de la crème."},{"q":"Peut-on congeler le plat ?","a":"Oui, mais la sauce peut se séparer. Décongelez au réfrigérateur et réchauffez doucement en remuant ; la texture est meilleure fraîche."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"57abe9a1-3a8e-4a90-8b28-4fefee556e3f"},{"language":"it","slug":"ceci-cremosi-pomodori-secchi-marry-me","public_path":"/it/ceci-cremosi-pomodori-secchi-marry-me","title":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas","excerpt":"Ceci in barattolo in una salsa cremosa con pomodori secchi, spinaci e parmigiano. La nostra versione di Marry Me Chickpeas si prepara in padella per quattro.","summary":"Ceci in barattolo in una salsa cremosa con pomodori secchi, spinaci e parmigiano. La nostra versione di Marry Me Chickpeas si prepara in padella per quattro.","notes":"<p>Usa ceci già cotti; quelli secchi richiedono una cottura separata. Il parmigiano tradizionale può contenere caglio animale: per una versione rigorosamente vegetariana scegli un formaggio con caglio microbico. Contiene latte. Riponi gli avanzi in frigorifero entro 2 ore e consumali entro 3 giorni; riscalda dolcemente con poca acqua. Il calcolo include tutto il sale indicato, anche se ne usi meno.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/pizza-beans-fagioli-mozzarella\">Pizza beans: fagioli bianchi al pomodoro e mozzarella</a></li><li><a href=\"/it/insalata-lenticchie-carote-senape\">Insalata di lenticchie e carote arrosto con senape di Digione</a></li></ul>","content_html":"<p>Ceci in barattolo in una salsa cremosa con pomodori secchi, spinaci e parmigiano. La nostra versione di Marry Me Chickpeas si prepara in padella per quattro.</p><p>Usa ceci già cotti; quelli secchi richiedono una cottura separata. Il parmigiano tradizionale può contenere caglio animale: per una versione rigorosamente vegetariana scegli un formaggio con caglio microbico. Contiene latte. Riponi gli avanzi in frigorifero entro 2 ore e consumali entro 3 giorni; riscalda dolcemente con poca acqua. Il calcolo include tutto il sale indicato, anche se ne usi meno.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/pizza-beans-fagioli-mozzarella\">Pizza beans: fagioli bianchi al pomodoro e mozzarella</a></li><li><a href=\"/it/insalata-lenticchie-carote-senape\">Insalata di lenticchie e carote arrosto con senape di Digione</a></li></ul>","ingredients":[{"name":"Ceci cotti, scolati","amount":"480","unit":"g"},{"name":"Cipolla sbucciata","amount":"100","unit":"g"},{"name":"Olio d’oliva","amount":"15","unit":"g"},{"name":"Aglio sbucciato","amount":"10","unit":"g"},{"name":"Pomodori secchi sott’olio, scolati","amount":"60","unit":"g"},{"name":"Concentrato di pomodoro","amount":"20","unit":"g"},{"name":"Brodo vegetale","amount":"200","unit":"ml"},{"name":"Panna al 35% di grassi","amount":"150","unit":"g"},{"name":"Spinaci freschi","amount":"100","unit":"g"},{"name":"Parmigiano grattugiato","amount":"30","unit":"g"},{"name":"Origano secco","amount":"1","unit":"g"},{"name":"Sale","amount":"2","unit":"g"},{"name":"Pepe nero macinato","amount":"0.5","unit":"g"}],"steps":[{"title":"Prepara gli ingredienti","content":"Scola e sciacqua i ceci fino a ottenere 480 g. Trita cipolla e aglio, taglia a strisce i pomodori scolati e lava gli spinaci.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-01.webp","image_alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas: Prepara gli ingredienti"},{"title":"Appassisci la cipolla","content":"Scalda 15 g d’olio in una padella ampia a fuoco medio. Cuoci la cipolla per 6–7 minuti mescolando, finché si ammorbidisce senza bruciare.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-02.webp","image_alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas: Appassisci la cipolla"},{"title":"Concentra i sapori","content":"Unisci aglio, pomodori secchi, 20 g di concentrato e origano. Mescola per 2 minuti per cuocere il concentrato di pomodoro.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-03.webp","image_alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas: Concentra i sapori"},{"title":"Aggiungi i ceci","content":"Versa 200 ml di brodo e raschia il fondo con un cucchiaio. Aggiungi i ceci e lascia sobbollire scoperto per 5 minuti.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-04.webp","image_alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas: Aggiungi i ceci"},{"title":"Unisci la panna","content":"Abbassa il fuoco e aggiungi 150 g di panna. Fai sobbollire molto dolcemente per 6–8 minuti, finché la salsa avvolge i ceci senza asciugarsi.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-05.webp","image_alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas: Unisci la panna"},{"title":"Fai appassire gli spinaci","content":"Aggiungi gli spinaci in due riprese e mescola per 2 minuti, finché perdono volume e si distribuiscono. Evita di bollirli più del necessario.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-06.webp","image_alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas: Fai appassire gli spinaci"},{"title":"Completa fuori dal fuoco","content":"Spegni e incorpora parmigiano e pepe. Assaggia prima di aggiungere i 2 g di sale: brodo e formaggio potrebbero già bastare.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-07.webp","image_alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas: Completa fuori dal fuoco"},{"title":"Servi","content":"Dividi in quattro piatti e servi caldo. Pane o riso d’accompagnamento non sono inclusi nelle quantità né nella nutrizione.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-08.webp","image_alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas: Servi"}],"category":"Secondi piatti","course":"Secondi piatti","cuisine":"Statunitense, ispirazione italiana","difficulty":"Facile","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas"}],"video_urls":[],"keywords":["Ceci cremosi con pomodori secchi: Marry Me Chickpeas","Ceci cotti, scolati","Cipolla sbucciata"],"nutrition":{"calories":415,"protein_g":14.5,"carbs_g":38.0,"fat_g":24.4,"saturated_fat_g":10.9,"fiber_g":9.8,"sodium_mg":759.0,"estimated":true,"serving_size":"1 di 4 porzioni","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Somma dei valori di riferimento per peso, divisa per le porzioni.","note":"Stima indicativa, non misurazione del piatto cotto. Marche e scolatura modificano i valori; nutrienti con dati incompleti non sono mostrati. Riferimenti generici per senape preparata, panna, patata dolce, olio e cioccolato; varietà e marche possono differire."},"seo":{"title":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas","description":"Ceci in barattolo in una salsa cremosa con pomodori secchi, spinaci e parmigiano. La nostra versione di Marry Me Chickpeas si prepara in padella per quattro.","image_alt":"Ceci cremosi con pomodori secchi: Marry Me Chickpeas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-16x9.webp"],"faq":[{"q":"Cosa significa Marry Me Chickpeas?","a":"È il nome comune di ceci in salsa cremosa con pomodori secchi, ispirati a Marry Me Chicken. Questa preparazione non contiene pollo."},{"q":"Posso sostituire la panna con latte?","a":"Non nella stessa quantità per questa consistenza. Il latte è meno grasso e addensa diversamente; la ricetta è calcolata con panna."},{"q":"Posso congelarli?","a":"Sì, ma la salsa può separarsi. Scongela in frigorifero e scalda delicatamente mescolando; appena fatta la consistenza è migliore."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"57abe9a1-3a8e-4a90-8b28-4fefee556e3f"},{"language":"ja","slug":"marry-me-chickpeas-cream-tomato","public_path":"/ja/marry-me-chickpeas-cream-tomato","title":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮","excerpt":"缶詰のひよこ豆をドライトマト、生クリーム、ほうれん草、パルメザンで煮る一品。フライパン1つで作るマリーミー・チックピーズ4人分です。","summary":"缶詰のひよこ豆をドライトマト、生クリーム、ほうれん草、パルメザンで煮る一品。フライパン1つで作るマリーミー・チックピーズ4人分です。","notes":"<p>すでにゆでたひよこ豆を使います。乾燥豆は別途調理が必要です。伝統的なパルメザンには動物性レンネットが使われることがあるため、厳密なベジタリアン向けには微生物由来レンネットのチーズを選びます。乳を含みます。残りは2時間以内に冷蔵し、3日以内に食べ、少量の水を加えて穏やかに再加熱します。栄養値は表示の塩を全量加えた計算です。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/pizza-beans\">ピザビーンズ：白いんげん豆のトマトチーズ焼き</a></li><li><a href=\"/ja/lentil-roasted-carrot-mustard-salad\">レンズ豆とローストにんじんのサラダ：粒なしマスタード風味</a></li></ul>","content_html":"<p>缶詰のひよこ豆をドライトマト、生クリーム、ほうれん草、パルメザンで煮る一品。フライパン1つで作るマリーミー・チックピーズ4人分です。</p><p>すでにゆでたひよこ豆を使います。乾燥豆は別途調理が必要です。伝統的なパルメザンには動物性レンネットが使われることがあるため、厳密なベジタリアン向けには微生物由来レンネットのチーズを選びます。乳を含みます。残りは2時間以内に冷蔵し、3日以内に食べ、少量の水を加えて穏やかに再加熱します。栄養値は表示の塩を全量加えた計算です。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/pizza-beans\">ピザビーンズ：白いんげん豆のトマトチーズ焼き</a></li><li><a href=\"/ja/lentil-roasted-carrot-mustard-salad\">レンズ豆とローストにんじんのサラダ：粒なしマスタード風味</a></li></ul>","ingredients":[{"name":"ゆでひよこ豆（水切り後）","amount":"480","unit":"g"},{"name":"玉ねぎ（皮を除く）","amount":"100","unit":"g"},{"name":"オリーブ油","amount":"15","unit":"g"},{"name":"にんにく（皮を除く）","amount":"10","unit":"g"},{"name":"オイル漬けドライトマト（油を切る）","amount":"60","unit":"g"},{"name":"トマトペースト","amount":"20","unit":"g"},{"name":"野菜ブロス","amount":"200","unit":"ml"},{"name":"生クリーム（乳脂肪35%）","amount":"150","unit":"g"},{"name":"ほうれん草","amount":"100","unit":"g"},{"name":"パルメザンチーズ（すりおろす）","amount":"30","unit":"g"},{"name":"乾燥オレガノ","amount":"1","unit":"g"},{"name":"塩","amount":"2","unit":"g"},{"name":"黒こしょう（粉）","amount":"0.5","unit":"g"}],"steps":[{"title":"材料を準備","content":"ひよこ豆を水切りして洗い、480 g量ります。玉ねぎとにんにくを刻み、油を切ったドライトマトを細切りにし、ほうれん草を洗います。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-01.webp","image_alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮: 材料を準備"},{"title":"玉ねぎを炒める","content":"大きなフライパンで油15 gを中火で熱します。玉ねぎを加え、焦がさず柔らかくなるまで6〜7分混ぜながら炒めます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-02.webp","image_alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮: 玉ねぎを炒める"},{"title":"うま味を引き出す","content":"にんにく、ドライトマト、トマトペースト20 g、オレガノを加えます。ペーストに火を通すよう2分炒めます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-03.webp","image_alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮: うま味を引き出す"},{"title":"豆を加える","content":"ブロス200 mlを注ぎ、底のうま味を木べらなどではがします。ひよこ豆を加え、ふたをせず弱く煮立てて5分煮ます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-04.webp","image_alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮: 豆を加える"},{"title":"生クリームを加える","content":"火を弱め、生クリーム150 gを加えます。ごく弱い沸騰を保って6〜8分、ソースが豆に絡むまで煮ます。煮詰めすぎないでください。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-05.webp","image_alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮: 生クリームを加える"},{"title":"ほうれん草を加える","content":"ほうれん草を2回に分けて加え、しんなりして全体になじむまで2分混ぜます。必要以上に煮続けません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-06.webp","image_alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮: ほうれん草を加える"},{"title":"火を止めて仕上げる","content":"火を止め、パルメザンとこしょうを混ぜます。塩2 gを加える前に味見をします。ブロスとチーズの塩分で十分な場合があります。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-07.webp","image_alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮: 火を止めて仕上げる"},{"title":"盛り付ける","content":"4皿に分けて温かく出します。添えるパンやご飯は、材料の分量にも栄養計算にも含めていません。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-08.webp","image_alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮: 盛り付ける"}],"category":"主菜","course":"主菜","cuisine":"イタリア風アメリカ料理","difficulty":"簡単","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮"}],"video_urls":[],"keywords":["マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮","ゆでひよこ豆（水切り後）","玉ねぎ（皮を除く）"],"nutrition":{"calories":415,"protein_g":14.5,"carbs_g":38.0,"fat_g":24.4,"saturated_fat_g":10.9,"fiber_g":9.8,"sodium_mg":759.0,"estimated":true,"serving_size":"全4人分のうち1人分","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"材料の重量に応じた参考栄養値を合計し、人数で割っています。","note":"調理済み料理の実測値ではなく概算です。商品や水切りで変わり、資料がそろわない栄養素は表示しません。 マスタード、生クリーム、さつまいも、油、チョコレートは一般的な参考値を使用し、品種や商品で異なります。"},"seo":{"title":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮","description":"缶詰のひよこ豆をドライトマト、生クリーム、ほうれん草、パルメザンで煮る一品。フライパン1つで作るマリーミー・チックピーズ4人分です。","image_alt":"マリーミー・チックピーズ：ひよこ豆のトマトクリーム煮","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-16x9.webp"],"faq":[{"q":"マリーミー・チックピーズとは？","a":"マリーミー・チキンをヒントにした、ひよこ豆とドライトマトのクリーム煮の通称です。このレシピに鶏肉は入りません。"},{"q":"生クリームを牛乳に替えられますか？","a":"同量では同じ濃度になりません。牛乳は脂肪が少なく、とろみの付き方が違います。この分量は生クリームで計算しています。"},{"q":"冷凍できますか？","a":"可能ですがソースが分離することがあります。冷蔵庫で解凍して混ぜながら弱く温めてください。作りたての食感が最良です。"}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"57abe9a1-3a8e-4a90-8b28-4fefee556e3f"},{"language":"pt","slug":"grao-de-bico-cremoso-tomate-seco","public_path":"/pt/grao-de-bico-cremoso-tomate-seco","title":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas","excerpt":"Grão-de-bico em conserva num molho cremoso com tomate seco, espinafre e parmesão. Nossa versão de Marry Me Chickpeas usa uma frigideira e rende quatro porções.","summary":"Grão-de-bico em conserva num molho cremoso com tomate seco, espinafre e parmesão. Nossa versão de Marry Me Chickpeas usa uma frigideira e rende quatro porções.","notes":"<p>Use grão-de-bico já cozido; o seco exige outra cocção. Parmesão tradicional pode conter coalho animal: para uma versão estritamente vegetariana, escolha queijo com coalho microbiano. Contém leite. Refrigere as sobras antes de 2 horas e consuma em até 3 dias; reaqueça suavemente com um pouco de água. A nutrição contabiliza todo o sal indicado, mesmo que você use menos.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/pizza-beans-feijao-mucarela\">Pizza beans: feijão branco com tomate e muçarela</a></li><li><a href=\"/pt/salada-lentilha-cenoura-mostarda\">Salada de lentilha com cenoura assada e mostarda Dijon</a></li></ul>","content_html":"<p>Grão-de-bico em conserva num molho cremoso com tomate seco, espinafre e parmesão. Nossa versão de Marry Me Chickpeas usa uma frigideira e rende quatro porções.</p><p>Use grão-de-bico já cozido; o seco exige outra cocção. Parmesão tradicional pode conter coalho animal: para uma versão estritamente vegetariana, escolha queijo com coalho microbiano. Contém leite. Refrigere as sobras antes de 2 horas e consuma em até 3 dias; reaqueça suavemente com um pouco de água. A nutrição contabiliza todo o sal indicado, mesmo que você use menos.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/pizza-beans-feijao-mucarela\">Pizza beans: feijão branco com tomate e muçarela</a></li><li><a href=\"/pt/salada-lentilha-cenoura-mostarda\">Salada de lentilha com cenoura assada e mostarda Dijon</a></li></ul>","ingredients":[{"name":"Grão-de-bico cozido e escorrido","amount":"480","unit":"g"},{"name":"Cebola descascada","amount":"100","unit":"g"},{"name":"Azeite de oliva","amount":"15","unit":"g"},{"name":"Alho descascado","amount":"10","unit":"g"},{"name":"Tomate seco em óleo, escorrido","amount":"60","unit":"g"},{"name":"Extrato de tomate","amount":"20","unit":"g"},{"name":"Caldo de legumes","amount":"200","unit":"ml"},{"name":"Creme de leite com 35% de gordura","amount":"150","unit":"g"},{"name":"Espinafre fresco","amount":"100","unit":"g"},{"name":"Queijo parmesão ralado","amount":"30","unit":"g"},{"name":"Orégano seco","amount":"1","unit":"g"},{"name":"Sal","amount":"2","unit":"g"},{"name":"Pimenta-do-reino moída","amount":"0.5","unit":"g"}],"steps":[{"title":"Prepare os ingredientes","content":"Escorra e enxágue o grão-de-bico até obter 480 g. Pique cebola e alho, corte os tomates escorridos em tiras e lave o espinafre.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-01.webp","image_alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas: Prepare os ingredientes"},{"title":"Refogue a cebola","content":"Aqueça 15 g de azeite numa frigideira grande em fogo médio. Refogue a cebola por 6–7 minutos, mexendo, até amaciar sem queimar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-02.webp","image_alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas: Refogue a cebola"},{"title":"Concentre o sabor","content":"Junte alho, tomate seco, 20 g de extrato e orégano. Mexa por 2 minutos para cozinhar o extrato de tomate.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-03.webp","image_alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas: Concentre o sabor"},{"title":"Junte o grão-de-bico","content":"Despeje 200 ml de caldo e raspe o fundo com uma colher. Junte o grão-de-bico e cozinhe em fervura branda, sem tampa, por 5 minutos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-04.webp","image_alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas: Junte o grão-de-bico"},{"title":"Acrescente o creme","content":"Abaixe o fogo e incorpore 150 g de creme de leite. Cozinhe bem suavemente por 6–8 minutos, até o molho envolver os grãos sem secar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-05.webp","image_alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas: Acrescente o creme"},{"title":"Murche o espinafre","content":"Junte o espinafre em duas levas e misture por 2 minutos, até murchar e se distribuir. Evite ferver mais do que o necessário.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-06.webp","image_alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas: Murche o espinafre"},{"title":"Finalize fora do fogo","content":"Desligue e misture parmesão e pimenta. Prove antes de adicionar os 2 g de sal: caldo e queijo podem já salgar o suficiente.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-07.webp","image_alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas: Finalize fora do fogo"},{"title":"Sirva","content":"Divida em quatro pratos e sirva quente. Pão ou arroz de acompanhamento não entram nas quantidades nem na nutrição da receita.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/paso-08.webp","image_alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas: Sirva"}],"category":"Pratos principais","course":"Pratos principais","cuisine":"Estadunidense, inspiração italiana","difficulty":"Fácil","prep_time_minutes":15,"cook_time_minutes":25,"total_time_minutes":40,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada.webp","alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas"}],"video_urls":[],"keywords":["Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas","Grão-de-bico cozido e escorrido","Cebola descascada"],"nutrition":{"calories":415,"protein_g":14.5,"carbs_g":38.0,"fat_g":24.4,"saturated_fat_g":10.9,"fiber_g":9.8,"sodium_mg":759.0,"estimated":true,"serving_size":"1 das 4 porções","source":"USDA FoodData Central SR Legacy","source_url":"https://fdc.nal.usda.gov/download-datasets/","method":"Soma das referências pelo peso dos ingredientes, dividida pelas porções.","note":"Estimativa orientativa, não medição do prato pronto. Marcas e escorrimento alteram os valores; nutrientes com dados incompletos não são mostrados. Referências genéricas para mostarda preparada, creme, batata-doce, óleo e chocolate; variedades e marcas podem diferir."},"seo":{"title":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas","description":"Grão-de-bico em conserva num molho cremoso com tomate seco, espinafre e parmesão. Nossa versão de Marry Me Chickpeas usa uma frigideira e rende quatro porções.","image_alt":"Grão-de-bico cremoso com tomate seco: Marry Me Chickpeas","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/garbanzos-cremosos-tomates-secos/portada-16x9.webp"],"faq":[{"q":"O que significa Marry Me Chickpeas?","a":"É o nome popular do grão-de-bico com molho cremoso e tomate seco, inspirado em Marry Me Chicken. Esta preparação não leva frango."},{"q":"Posso usar leite no lugar do creme?","a":"Não na mesma proporção para essa textura. Leite tem menos gordura e engrossa de outra forma; a formulação foi calculada com creme de leite."},{"q":"Posso congelar?","a":"Sim, mas o molho pode separar. Descongele na geladeira e reaqueça suavemente, mexendo; a textura é melhor na hora."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"57abe9a1-3a8e-4a90-8b28-4fefee556e3f"}]$expected$::jsonb; x jsonb; v public.recipes; n int:=0;
BEGIN
 IF jsonb_array_length(j)<>7 THEN RAISE EXCEPTION 'Expected 7 records'; END IF;
 IF (SELECT count(*) FROM public.recipes r JOIN jsonb_array_elements(j) e ON r.public_path=e->>'public_path' AND r.recipe_group_id=(e->>'recipe_group_id')::uuid AND r.language=e->>'language')<>7 THEN RAISE EXCEPTION 'Group identity mismatch'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(j) LOOP
  SELECT * INTO STRICT v FROM public.recipes WHERE public_path=x->>'public_path' AND recipe_group_id=(x->>'recipe_group_id')::uuid FOR UPDATE;
  IF v.published OR v.title IS DISTINCT FROM x->>'title' OR v.ingredients IS DISTINCT FROM x->'ingredients' OR v.steps IS DISTINCT FROM x->'steps' OR v.nutrition IS DISTINCT FROM x->'nutrition' OR v.seo IS DISTINCT FROM x->'seo' OR v.image_url IS DISTINCT FROM x->>'image_url' OR v.content_html IS DISTINCT FROM x->>'content_html' OR v.total_time_minutes IS DISTINCT FROM (x->>'total_time_minutes')::int THEN RAISE EXCEPTION 'Draft changed or already published: %',v.public_path; END IF;
 END LOOP;
 PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Missing admin context'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(j) LOOP
  SELECT * INTO STRICT v FROM public.recipes WHERE public_path=x->>'public_path' AND recipe_group_id=(x->>'recipe_group_id')::uuid;
  UPDATE public.recipes SET editorial_status='ready',ready_at=now(),reviewed_at=now(),reviewed_by='Codex editorial QA, owner-authorized 2026-10-28' WHERE id=v.id;
  PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
  UPDATE public.recipes SET editorial_status='published',published_by='Codex owner-authorized siete mercados 2026-10-28' WHERE id=v.id;
  n:=n+1;
 END LOOP;
 IF n<>7 THEN RAISE EXCEPTION 'Expected 7 publications'; END IF;
END $publish$;
